# Winter hay calculator
CALC = '<section class="calc" aria-label="Winter hay calculator">\n  <form class="panel" id="hayform" autocomplete="off">\n    <h2>Your herd and your setup</h2>\n    <div class="grid">\n      <label>Animal\n        <select id="species">\n          <option value="horse" data-pct="2" data-wt="1100">Horse</option>\n          <option value="pony" data-pct="1.75" data-wt="600">Pony / mini</option>\n          <option value="donkey" data-pct="1.5" data-wt="500">Donkey</option>\n          <option value="cow" data-pct="2.5" data-wt="1200">Beef cow (dry)</option>\n          <option value="cow-lact" data-pct="3" data-wt="1200">Beef cow (nursing a calf)</option>\n          <option value="goat" data-pct="3.5" data-wt="140">Goat</option>\n          <option value="sheep" data-pct="3" data-wt="160">Sheep</option>\n          <option value="alpaca" data-pct="1.5" data-wt="150">Alpaca / llama</option>\n        </select>\n      </label>\n      <label>How many\n        <input id="count" type="number" min="1" step="1" value="2" inputmode="numeric">\n      </label>\n      <label>Average weight <small>pounds each</small>\n        <input id="weight" type="number" min="50" step="10" value="1100" inputmode="numeric">\n      </label>\n      <label>Hay intake <small>% of body weight per day</small>\n        <input id="pct" type="number" min="0.5" max="5" step="0.25" value="2" inputmode="decimal">\n      </label>\n      <label>Days you\'ll feed hay <small>North Georgia: ~150 (Nov–Mar)</small>\n        <input id="days" type="number" min="1" max="365" step="1" value="150" inputmode="numeric">\n      </label>\n      <label>Grain or feed fed <small>lbs per animal per day, subtracts from hay</small>\n        <input id="grain" type="number" min="0" step="0.5" value="0" inputmode="decimal">\n      </label>\n      <label>Feeder type <small>sets feeding waste</small>\n        <select id="feeder">\n          <option value="13">On the ground — 13% waste</option>\n          <option value="5" selected>Hay rack / net — 5%</option>\n          <option value="3">Basket or slow feeder — 3%</option>\n          <option value="20">Round bale, no ring — 20%</option>\n          <option value="9">Round bale in ring — 9%</option>\n        </select>\n      </label>\n      <label>Where it\'s stored <small>sets storage loss</small>\n        <select id="storage">\n          <option value="5" selected>Inside a barn — 5%</option>\n          <option value="12">Outside, tarped, on pallets — 12%</option>\n          <option value="25">Outside, uncovered — 25%</option>\n        </select>\n      </label>\n      <label>Bale weight <small>pounds</small>\n        <input id="bale" type="number" min="20" step="5" value="50" inputmode="numeric">\n      </label>\n      <label>Price per bale <small>$, leave 0 to skip</small>\n        <input id="price" type="number" min="0" step="0.25" value="8" inputmode="decimal">\n      </label>\n      <label>Safety margin <small>% extra for a late spring</small>\n        <input id="margin" type="number" min="0" max="50" step="5" value="10" inputmode="numeric">\n      </label>\n    </div>\n  </form>\n\n  <aside class="panel results" aria-live="polite">\n    <div class="tag">\n      <div class="lbl">Buy this much</div>\n      <div class="big" id="r-bales">—</div>\n      <div class="sub" id="r-tons">—</div>\n    </div>\n    <dl class="rows">\n      <dt>Hay eaten per day, whole herd</dt><dd id="r-daily">—</dd>\n      <dt>Eaten over the season</dt><dd id="r-eaten">—</dd>\n      <dt>Feeding waste</dt><dd id="r-fw">—</dd>\n      <dt>Storage loss</dt><dd id="r-sw">—</dd>\n      <dt>Safety margin</dt><dd id="r-mg">—</dd>\n      <dt class="total">Total to put up</dt><dd class="total" id="r-total">—</dd>\n      <dt class="total">Estimated cost</dt><dd class="total cost" id="r-cost">—</dd>\n    </dl>\n    <p class="note" id="r-note"></p>\n    <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">\n      <button class="btn" type="button" id="copy">Copy summary</button>\n      <button class="btn ghost" type="button" id="reset">Reset</button>\n      <span class="copied" id="copied" hidden>Copied</span>\n    </div>\n  </aside>\n</section>'
ARTICLE_PRE = '<article>\n  <h2>How the calculator works</h2>\n  <p>Extension offices from North Carolina to Minnesota teach the same four-step method. We just do the arithmetic for you.</p>\n  <div class="formula">body weight × intake % × days × animals, then × (1 + feeding waste) × (1 + storage loss)</div>\n  <p>A mature horse eats about 2% of its body weight in hay each day when hay is the whole ration. For an 1,100-pound horse that\'s 22 pounds. Over a 150-day feeding season that is 3,300 pounds before waste. Add 5% storage loss and 13% ground-feeding waste and you\'re at roughly 3,900 pounds, almost two tons, or about 98 fifty-pound bales per horse.</p>\n\n  <h2>Daily hay intake by animal</h2>\n  <p>These are the defaults the calculator uses. Working animals, pregnant or nursing animals, and animals in hard cold need more; easy keepers on good pasture need less.</p>\n  <div class="tbl"><table>\n    <thead><tr><th>Animal</th><th>Typical weight</th><th>Hay as % of body weight</th><th>Pounds per day</th></tr></thead>\n    <tbody>\n      <tr><td>Horse (maintenance)</td><td>1,100 lb</td><td>1.5–2.5%</td><td>17–28</td></tr>\n      <tr><td>Pony or miniature</td><td>600 lb</td><td>1.5–2%</td><td>9–12</td></tr>\n      <tr><td>Donkey</td><td>500 lb</td><td>1.25–1.75%</td><td>6–9</td></tr>\n      <tr><td>Beef cow, dry</td><td>1,200 lb</td><td>2–2.5%</td><td>24–30</td></tr>\n      <tr><td>Beef cow, nursing</td><td>1,200 lb</td><td>2.5–3%</td><td>30–36</td></tr>\n      <tr><td>Goat</td><td>140 lb</td><td>3–4%</td><td>4–6</td></tr>\n      <tr><td>Sheep</td><td>160 lb</td><td>2.5–3.5%</td><td>4–6</td></tr>\n      <tr><td>Alpaca / llama</td><td>150 lb</td><td>1.25–1.75%</td><td>2–3</td></tr>\n    </tbody>\n  </table></div>\n\n  <h2>How much hay gets wasted</h2>\n  <p>University of Minnesota researchers measured how much hay horses trample, soil and refuse with different feeders. Feeding small square bales on bare ground wasted about 13%. A hay rack cut that to 5%, and a basket-style feeder to 3%. For round bales with no feeder at all, losses run 20% or more; a ring feeder brings it near 9%.</p>\n  <p>Storage matters just as much. Hay kept dry inside a barn loses about 5% to spoilage and handling. Stacked outside under a tarp on pallets, expect 10–15%. Left uncovered on the ground, a quarter of the stack can rot before you feed it.</p>\n\n  <h2>How many days will you feed hay?</h2>\n  <p>Count from when your pasture quits growing to when it comes back strong enough to carry the animals. In the Southeast that is usually November through March, about 150 days. Across the Midwest and Northeast plan on 180–210 days. If you overseed winter rye or stockpile fescue, you can trim a few weeks off.</p>\n\n  <h2>Bale weights are not what the seller says</h2>\n  <p>"Fifty-pound squares" range from 35 to 70 pounds depending on the baler, the cut and how dry it was. Round bales run anywhere from 600 to 1,500 pounds. Weigh a few bales on a bathroom scale (hold one, subtract yourself) before you trust a bale count. Buying by the ton is the only way to compare prices fairly.</p>\n\n  <h2>Frequently asked</h2>\n  '
ARTICLE_POST = '\n</article>'
TAIL = "</div>\n\n<script>\n(function(){\n  var $=function(id){return document.getElementById(id)};\n  var f={species:$('species'),count:$('count'),weight:$('weight'),pct:$('pct'),days:$('days'),grain:$('grain'),feeder:$('feeder'),storage:$('storage'),bale:$('bale'),price:$('price'),margin:$('margin')};\n  var fmt=function(n,d){return n.toLocaleString('en-US',{maximumFractionDigits:d==null?0:d,minimumFractionDigits:d==null?0:d})};\n  var usd=function(n){return '$'+fmt(n,0)};\n  var last='';\n\n  function calc(){\n    var count=Math.max(0,+f.count.value||0), wt=Math.max(0,+f.weight.value||0), pct=Math.max(0,+f.pct.value||0);\n    var days=Math.max(0,+f.days.value||0), grain=Math.max(0,+f.grain.value||0);\n    var fw=(+f.feeder.value||0)/100, sw=(+f.storage.value||0)/100, bale=Math.max(1,+f.bale.value||50);\n    var price=Math.max(0,+f.price.value||0), mg=Math.max(0,+f.margin.value||0)/100;\n\n    var perDay=Math.max(0, wt*pct/100 - grain);\n    var daily=perDay*count;\n    var eaten=daily*days;\n    var feedWaste=eaten*fw;\n    var afterFeed=eaten+feedWaste;\n    var storeWaste=afterFeed*sw;\n    var base=afterFeed+storeWaste;\n    var margin=base*mg;\n    var total=base+margin;\n    var bales=Math.ceil(total/bale);\n    var tons=total/2000;\n    var cost=price>0?bales*price:null;\n\n    $('r-bales').textContent=fmt(bales)+' bales';\n    $('r-tons').textContent=fmt(tons,1)+' tons at '+fmt(bale)+' lb per bale';\n    $('r-daily').textContent=fmt(daily,1)+' lb';\n    $('r-eaten').textContent=fmt(eaten)+' lb';\n    $('r-fw').textContent='+ '+fmt(feedWaste)+' lb';\n    $('r-sw').textContent='+ '+fmt(storeWaste)+' lb';\n    $('r-mg').textContent='+ '+fmt(margin)+' lb';\n    $('r-total').textContent=fmt(total)+' lb';\n    $('r-cost').textContent=cost==null?'—':usd(cost);\n    var sp=f.species.options[f.species.selectedIndex].text;\n    $('r-note').textContent=count+' '+sp.toLowerCase()+(count==1?'':'s')+' × '+fmt(perDay,1)+' lb hay/day each × '+days+' days'+(grain?' (after '+grain+' lb grain)':'')+'. Round bales: divide pounds by your bale weight.';\n\n    last='Winter hay estimate: '+count+' '+sp+' at '+fmt(wt)+' lb, '+pct+'% BW, '+days+' days. Eaten '+fmt(eaten)+' lb, waste '+fmt(feedWaste+storeWaste)+' lb, margin '+fmt(margin)+' lb. Buy '+fmt(total)+' lb = '+fmt(tons,1)+' tons = '+bales+' bales @ '+bale+' lb'+(cost!=null?' ≈ '+usd(cost):'')+'.';\n  }\n\n  f.species.addEventListener('change',function(){\n    var o=f.species.options[f.species.selectedIndex];\n    f.pct.value=o.getAttribute('data-pct'); f.weight.value=o.getAttribute('data-wt'); calc();\n  });\n  Object.keys(f).forEach(function(k){ f[k].addEventListener('input',calc); });\n  $('hayform').addEventListener('submit',function(e){e.preventDefault();calc();});\n  $('reset').addEventListener('click',function(){\n    f.species.value='horse';f.count.value=2;f.weight.value=1100;f.pct.value=2;f.days.value=150;f.grain.value=0;f.feeder.value='5';f.storage.value='5';f.bale.value=50;f.price.value=8;f.margin.value=10;calc();\n  });\n  $('copy').addEventListener('click',function(){\n    var done=function(){$('copied').hidden=false;setTimeout(function(){$('copied').hidden=true},1800)};\n    if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(last).then(done,function(){fallback()})}else{fallback()}\n    function fallback(){var t=document.createElement('textarea');t.value=last;document.body.appendChild(t);t.select();try{document.execCommand('copy');done()}catch(e){}document.body.removeChild(t)}\n  });\n  calc();\n})();\n</script>"

FAQS=[
("How many bales of hay does a horse need for winter?","Roughly 80 to 100 fifty-pound square bales for an average 1,100-pound horse over a 150-day season, once you include normal waste. Longer winters, heavier horses and ground feeding push that past 120."),
("How many round bales for one horse?","At 800 pounds per round bale and a 150-day season with ring-feeder waste, figure 4 to 5 bales per horse. A horse on a free-choice round bale with no ring will go through one about every 10 to 12 days."),
("How much hay does a cow eat per day?","A dry 1,200-pound beef cow eats 24 to 30 pounds of hay a day. Once she is nursing a calf that climbs to 30 to 36 pounds. Through a 150-day winter, a single cow needs about two and a half tons after waste."),
("Should I subtract grain from the hay number?","Yes, if you feed a meaningful amount. Total dry-matter intake stays near 2% of body weight, so every pound of grain displaces roughly a pound of hay. The calculator does this when you enter a grain amount."),
("Is it better to buy all my winter hay at once?","Usually. Late-summer and early-fall prices are lowest and the quality is best. By February supply is thin and whatever is left is often the hay nobody wanted in September."),
]
GEAR=[
("Slow-feed hay net or basket feeder","Drops ground waste from 13% to about 3%. On two horses that's roughly 20 bales a winter.","https://www.tractorsupply.com/tsc/search/hay%20feeder","Shop hay feeders"),
("Heavy hay tarp + pallets","If your stack lives outside, getting it off the ground and under cover cuts storage loss in half.","https://www.tractorsupply.com/tsc/search/hay%20tarp","Shop hay tarps"),
("Livestock weight tape","Your guess at body weight is probably 100 lb off. A $10 tape fixes the biggest input in this math.","https://www.amazon.com/s?k=horse+weight+tape","Shop weight tapes"),
("Round bale ring feeder","Turns a 20% loss on an unprotected round bale into about 9%.","https://www.tractorsupply.com/tsc/search/round%20bale%20feeder","Shop bale rings"),
]

def build(page,header,footer,gear,faq_html):
    body='<div class="wrap">\n'+header('Livestock','How much hay do you need for winter?','Enter your animals and how you feed. We figure daily intake, add storage and feeder waste the way extension agents do, and turn it into tons, bales and dollars.')+'\n'+CALC+'\n'+gear('Cut the waste before you buy more hay','Every point of waste above is hay you paid for and never fed. These are the fixes that move the number the most.',GEAR)+'\n'+ARTICLE_PRE+faq_html(FAQS)+ARTICLE_POST+'\n'+footer('Formulas and waste rates from NC State Extension, University of Maryland Extension, University of Minnesota equine research and Oregon State Small Farms.')+'\n'+TAIL
    return page('winter-hay-calculator','Winter Hay Calculator: How Much Hay Do You Need? | Back Forty Tools','Winter Hay Calculator: How Much Hay Do You Need?','Free winter hay calculator for horses, cattle, goats, sheep and donkeys. Enter your animals, feeding days and feeder type to get pounds, tons, bale count and cost, with waste built in.',body,FAQS,'Winter Hay Calculator')
